  match r, t with
  | 1, (StA, S0) => [SWin 1]
  | 1, (StA, S1) => [SWin 2;SCycR 2;SWin 1]
  | 1, (StB, S0) => [SWin 2;SCycR 2;SWinR 5]
  | 1, (StB, S1) => [SWin 2]
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 1, (StC, S1) => [SWin 2;SCycR 2;SWinR 6]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 2;SCycR 2;SWinR 8]
  | _, _ => []
  end.

